package com.bank.kda.compare;

// What a streaming job needs, used to pick the right service.
class ProcessingRequirement {
    final String name;
    final boolean needsKeyedState;
    final boolean needsEventTimeWindows;
    final boolean needsJoinsOrCep;
    final boolean needsExactlyOnce;

    ProcessingRequirement(String name, boolean keyedState, boolean eventTimeWindows,
                          boolean joinsOrCep, boolean exactlyOnce) {
        this.name = name;
        this.needsKeyedState = keyedState;
        this.needsEventTimeWindows = eventTimeWindows;
        this.needsJoinsOrCep = joinsOrCep;
        this.needsExactlyOnce = exactlyOnce;
    }

    boolean isComplex() {
        return needsKeyedState || needsEventTimeWindows || needsJoinsOrCep || needsExactlyOnce;
    }
}
