package com.bank.kda.compare;

// A streaming service and the capabilities it supports.
interface StreamService {
    String name();
    boolean supportsKeyedState();
    boolean supportsEventTimeWindows();
    boolean supportsJoinsOrCep();
    boolean supportsExactlyOnce();

    default boolean canSatisfy(ProcessingRequirement r) {
        return (!r.needsKeyedState || supportsKeyedState())
            && (!r.needsEventTimeWindows || supportsEventTimeWindows())
            && (!r.needsJoinsOrCep || supportsJoinsOrCep())
            && (!r.needsExactlyOnce || supportsExactlyOnce());
    }
}
