package com.bank.kda.compare;

import java.util.List;
import java.util.logging.Logger;

// Picks the simplest service that satisfies the requirement, preferring
// SQL-only ONLY for simple jobs, else managed Flink.
class ServiceSelector {
    private static final Logger log = Logger.getLogger(ServiceSelector.class.getName());

    private final SqlOnlyService sqlOnly = new SqlOnlyService();
    private final ManagedFlinkService flink = new ManagedFlinkService();

    StreamService select(ProcessingRequirement r) {
        if (!r.isComplex() && sqlOnly.canSatisfy(r)) {
            log.info(() -> "'" + r.name + "' is simple -> " + sqlOnly.name());
            return sqlOnly;
        }
        log.info(() -> "'" + r.name + "' is complex (state/window/join/eos) -> " + flink.name());
        return flink;
    }

    void report(List<ProcessingRequirement> reqs) {
        for (ProcessingRequirement r : reqs) {
            StreamService chosen = select(r);
            log.info(() -> "DECISION " + r.name + " => " + chosen.name());
        }
    }
}
