package com.bank.kda.compare;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class KdaComparisonDemo {
    private static final Logger log = Logger.getLogger(KdaComparisonDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        // Simple filter: amount > threshold into an alert stream.
        ProcessingRequirement simpleFilter = new ProcessingRequirement(
                "high-value-filter", false, false, false, false);

        // Complex fraud engine: per-account state, event-time windows, CEP, EOS.
        ProcessingRequirement fraudEngine = new ProcessingRequirement(
                "fraud-engine", true, true, true, true);

        ServiceSelector selector = new ServiceSelector();
        selector.report(List.of(simpleFilter, fraudEngine));
    }
}

